function lfParse(text){
  if(typeof text!=='string'||!text.trim()) return { value:null, error:'棋盘为空' };
  var rows=text.split('\n').filter(function(r){ return r.length>0; });
  var w=rows[0].length;
  var grid=[];
  for(var y=0;y<rows.length;y++){
    if(rows[y].length!==w) return { value:null, error:'第 '+(y+1)+' 行宽度不一致' };
    var row=[];
    for(var x=0;x<w;x++){
      var ch=rows[y].charAt(x);
      if(ch!=='.'&&ch!=='O'&&ch!=='o'&&ch!=='*') return { value:null, error:'第 '+(y+1)+' 行含非法字符 "'+ch+'"（只允许 . O o *）' };
      row.push(ch==='.'?0:1);
    }
    grid.push(row);
  }
  return { value:grid, error:null };
}
function lfStep(grid){
  var h=grid.length, w=grid[0].length, next=[];
  for(var y=0;y<h;y++){
    var row=[];
    for(var x=0;x<w;x++){
      var n=0;
      for(var dy=-1;dy<=1;dy++) for(var dx=-1;dx<=1;dx++){
        if(dx===0&&dy===0) continue;
        var yy=(y+dy+h)%h, xx=(x+dx+w)%w;
        n+=grid[yy][xx];
      }
      row.push(grid[y][x]===1 ? (n===2||n===3?1:0) : (n===3?1:0));
    }
    next.push(row);
  }
  return next;
}
function lfRun(grid, gens){
  var g=grid, hist=[lfHash(g)];
  for(var i=0;i<gens;i++){
    g=lfStep(g);
    var hsh=lfHash(g);
    if(hist.indexOf(hsh)!==-1) return { grid:g, generations:i+1, cycle:true, period:i+1-hist.indexOf(hsh) };
    hist.push(hsh);
  }
  return { grid:g, generations:gens, cycle:false, period:0 };
}
function lfHash(grid){
  var s='';
  for(var y=0;y<grid.length;y++) s+=grid[y].join('');
  return s;
}
function lfCount(grid){
  var n=0;
  for(var y=0;y<grid.length;y++) for(var x=0;x<grid[0].length;x++) n+=grid[y][x];
  return n;
}
function lfPattern(name, size){
  var s=Math.max(8, size||20), grid=[], y, x;
  for(y=0;y<s;y++){ var r=[]; for(x=0;x<s;x++) r.push(0); grid.push(r); }
  var P={
    glider:[[1,2],[2,3],[3,1],[3,2],[3,3]],
    blinker:[[2,1],[2,2],[2,3]],
    block:[[1,1],[1,2],[2,1],[2,2]],
    pulsar:[]
  };
  if(name==='pulsar'){
    var seg=[2,3,4,8,9,10], off=[0,5,7,12], i, j;
    for(i=0;i<seg.length;i++) for(j=0;j<off.length;j++){
      P.pulsar.push([off[j]+1, seg[i]+1]); P.pulsar.push([seg[i]+1, off[j]+1]);
    }
    if(s<16) return { value:null, error:'Pulsar 需要至少 16×16 网格' };
  }
  var cells=P[name];
  if(!cells) return { value:null, error:'未知图案: '+name };
  for(var k=0;k<cells.length;k++){
    if(cells[k][0]>=s||cells[k][1]>=s) return { value:null, error:'网格太小放不下该图案' };
    grid[cells[k][0]][cells[k][1]]=1;
  }
  return { value:grid, error:null };
}
function lfText(grid){
  var lines=[];
  for(var y=0;y<grid.length;y++){
    var s='';
    for(var x=0;x<grid[0].length;x++) s+=grid[y][x]?'O':'.';
    lines.push(s);
  }
  return lines.join('\n');
}
function lfSvg(grid){
  var h=grid.length, w=grid[0].length, C=Math.max(8, Math.min(22, Math.floor(560/w)));
  var W=w*C+2, H=h*C+2;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    s+='<rect x="'+(x*C+1)+'" y="'+(y*C+1)+'" width="'+(C-1)+'" height="'+(C-1)+'" rx="2" fill="'+(grid[y][x]?'#10B981':'#141417')+'"/>';
  }
  s+='</svg>';
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lfParse:lfParse, lfStep:lfStep, lfRun:lfRun, lfCount:lfCount, lfPattern:lfPattern, lfText:lfText, lfHash:lfHash, lfSvg:lfSvg };
}
if (typeof window !== 'undefined') {
  window.LifeForgePure = { lfParse:lfParse, lfStep:lfStep, lfRun:lfRun, lfCount:lfCount, lfPattern:lfPattern, lfText:lfText, lfHash:lfHash, lfSvg:lfSvg };
}
